// Formatting library for C++ - the C API
//
// Copyright (c) 2012 - present, Victor Zverovich
// All rights reserved.
//
// For the license information refer to format.h.

#include "fmt/fmt-c.h"

#include <vector>

#include "fmt/format.h"

namespace {

auto make_arg(const fmt_arg& arg) -> fmt::format_arg {
  switch (arg.type) {
  case fmt_type_int:         return fmt::format_arg(arg.value.int_value);
  case fmt_type_uint:        return fmt::format_arg(arg.value.uint_value);
  case fmt_type_bool:        return fmt::format_arg(arg.value.bool_value);
  case fmt_type_char:        return fmt::format_arg(arg.value.char_value);
  case fmt_type_double:      return fmt::format_arg(arg.value.double_value);
  case fmt_type_long_double:
    return fmt::format_arg(arg.value.long_double_value);
  case fmt_type_cstring:     return fmt::format_arg(arg.value.cstring_value);
  case fmt_type_pointer:     return fmt::format_arg(arg.value.pointer_value);
  }
  FMT_THROW(fmt::format_error("invalid argument type"));
}

auto make_args(const fmt_arg* args, size_t num_args)
    -> std::vector<fmt::format_arg> {
  std::vector<fmt::format_arg> result;
  result.reserve(num_args);
  for (size_t i = 0; i < num_args; ++i) result.push_back(make_arg(args[i]));
  return result;
}

}  // namespace

extern "C" {

int fmt_vformat(char* buffer, size_t size, const char* fmt,
                const fmt_arg* args, size_t num_args) {
  try {
    auto fmt_args = make_args(args, num_args);
    auto result = fmt::vformat_to_n(
        buffer, size, fmt,
        fmt::format_args(fmt_args.data(), static_cast<int>(num_args)));
    if (size != 0) buffer[result.size < size ? result.size : size - 1] = '\0';
    return static_cast<int>(result.size);
  } catch (...) {
    return -1;
  }
}

int fmt_vfprint(FILE* f, const char* fmt, const fmt_arg* args,
                size_t num_args) {
  try {
    auto fmt_args = make_args(args, num_args);
    auto s = fmt::vformat(
        fmt, fmt::format_args(fmt_args.data(), static_cast<int>(num_args)));
    if (std::fwrite(s.data(), 1, s.size(), f) != s.size()) return -1;
    return static_cast<int>(s.size());
  } catch (...) {
    return -1;
  }
}

}  // extern "C"
