  char buf[10];
  EXPECT_LT(fmt_vformat(buf, sizeof(buf), "{", nullptr, 0), 0);
  EXPECT_LT(fmt_vformat(buf, sizeof(buf), "{}", nullptr, 0), 0);
  fmt_arg args[] = {fmt_from_cstring(nullptr)};
  EXPECT_LT(fmt_vformat(buf, sizeof(buf), "{}", args, 1), 0);
}

